const { EventEmitter } = require('events');
const ee = new EventEmitter();
const log = [];
ee.on('data', x => log.push('on:' + x));
ee.once('tick', () => log.push('once:tick'));
ee.emit('data', 1);
ee.emit('data', 2);
ee.emit('tick');
ee.emit('tick');
ee.on('error', e => log.push('caught:' + e.message));
